<?php
require_once __DIR__.'/includes/layout.php';
require_once __DIR__.'/includes/import_csv.php';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='import_csv') importer('nghia','nghia.php');
require_role(['SO','HOI_DONG']);
if($_SERVER['REQUEST_METHOD']==='POST')task('nghia.php',function(PDO $db,array $u){if(!in_array($u['vai_tro'],['SO','HOI_DONG'],true))throw new RuntimeException('Vai trò không được phân công chấm thi.');$tui=required_val('ma_tui');$a=required_val('ma_cbct1');$b=required_val('ma_cbct2');if($a===$b)throw new RuntimeException('Hai cán bộ chấm phải khác nhau.');$db->beginTransaction();try{$q=$db->prepare('SELECT COUNT(*) FROM nhan_su WHERE ma_ns IN (?,?) AND loai_nhan_su=?');$q->execute([$a,$b,'CHAM_THI']);if((int)$q->fetchColumn()!==2)throw new RuntimeException('Cả hai phải là nhân sự chấm thi hợp lệ.');$q=$db->prepare('INSERT INTO phan_cong_cham_thi(ma_tui,ma_cbct1,ma_cbct2) VALUES(?,?,?)');$q->execute([$tui,$a,$b]);audit($db,$u['id'],'PHAN_CONG_CHAM_THI',$tui.' -> '.$a.' + '.$b);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}});
page_start('Phân công Hội đồng chấm thi','nghia');echo '<div class="note">Mỗi túi bài có hai cán bộ chấm khác nhau. Không hiển thị SBD hoặc thông tin thí sinh trong phân hệ chấm thi. Phân công đã tồn tại không được ghi đè tùy tiện.</div><div class="panel"><h2>Phân công túi bài</h2>';form_open();select_field('ma_tui','Túi bài thi','SELECT ma_tui,ma_bi FROM tui_bai_thi ORDER BY ma_tui','ma_tui','ma_bi');select_field('ma_cbct1','Cán bộ chấm 1',"SELECT ma_ns,ho_ten FROM nhan_su WHERE loai_nhan_su='CHAM_THI'",'ma_ns','ho_ten');select_field('ma_cbct2','Cán bộ chấm 2',"SELECT ma_ns,ho_ten FROM nhan_su WHERE loai_nhan_su='CHAM_THI'",'ma_ns','ho_ten');form_close('Xác nhận phân công');echo '</div><div class="panel"><h2>Danh sách phân công</h2>';table_rows(db()->query('SELECT pc.ma_tui,mon.ten_mon,ns1.ho_ten,ns2.ho_ten,pc.trang_thai FROM phan_cong_cham_thi pc JOIN tui_bai_thi t ON pc.ma_tui=t.ma_tui JOIN mon_thi mon ON t.ma_mon=mon.ma_mon JOIN nhan_su ns1 ON ns1.ma_ns=pc.ma_cbct1 JOIN nhan_su ns2 ON ns2.ma_ns=pc.ma_cbct2')->fetchAll(),['Túi bài','Môn','Cán bộ 1','Cán bộ 2','Trạng thái']);echo '</div>';import_panel('nghia','Phân công chấm thi');page_end();
